Here's a Python program that meets your requirements. This program uses a dictionary to store the contacts and allows users to add, remove, and search for contacts.

```python
# Initialize the phonebook dictionary
phonebook = {}

def add_contact(name, number):
    """Add a contact to the phonebook."""
    if name in phonebook:
        print(f"{name}: {number}, Contact already exists.")
    else:
        phonebook[name] = number
        print(f"{name}: {number}, Contact added successfully.")

def remove_contact(name):
    """Remove a contact from the phonebook."""
    if name in phonebook:
        del phonebook[name]
        print(f"Contact {name} removed successfully.")
    else:
        print(f"Contact not found.")

def search_contact(name):
    """Search for a contact in the phonebook."""
    if name in phonebook:
        print(f"{name}: {phonebook[name]}")
    else:
        print(f"Contact not found.")

# User input
user_input = input("Enter a command (add, remove, search): ").lower()

if user_input == "add":
    name = input("Enter name: ")
    number = input("Enter phone number: ")
    add_contact(name, number)
elif user_input == "remove":
    name = input("Enter name: ")
    remove_contact(name)
elif user_input == "search":
    name = input("Enter name: ")
    search_contact(name)
else:
    print("Invalid command. Please try again.")
```

This program will continue to run until the user enters "quit" or any other command that is not "add", "remove", or "search".
